import React, { useState } from "react";

const categories = [
  "Housing",
  "Food",
  "Transportation",
  "Savings",
  "Entertainment",
  "Healthcare"
];

function SpendingPriority({ onNext }) {
  const [selected, setSelected] = useState({});
  const [active, setActive] = useState(null);

  const handleSlider = (category, value) => {
    setSelected({ ...selected, [category]: Number(value) });
  };

  return (
    <div className="income-container">
      <h2 className="income-title">Spending Priorities</h2>

      <div className="income-grid">
        {categories.map((cat) => (
          <div
            key={cat}
            className="income-card"
            onClick={() => setActive(cat)}
          >
            <div className="income-name">{cat}</div>

            {active === cat && (
              <input
                type="range"
                min="0"
                max="5"
                value={selected[cat] || 0}
                onChange={(e) => handleSlider(cat, e.target.value)}
              />
            )}
          </div>
        ))}
      </div>

      <button className="next-button" onClick={() => onNext(selected)}>
        Continue
      </button>
    </div>
  );
}

export default SpendingPriority;
